// slugify('Hello World!') is 'hello-world'. Accented letters keep their base letter:
// 'Crème Brûlée' is 'creme-brulee'. No leading, trailing or repeated dashes.
function slugify(text) {
  return text.toLowerCase().replace(/[^a-z0-9]+/g, '-');
}

module.exports = { slugify };

input.new_string:
test('ascii', () => {
  assert.strictEqual(slugify('hello world'), 'hello-world');
});

test('accented letters keep their base letter', () => {
  assert.strictEqual(slugify('Crème Brûlée'), 'creme-brulee');
  assert.strictEqual(slugify('Ångström Señor Zoë'), 'angstrom-senor-zoe');
});

test('no leading, trailing or repeated dashes', () => {
  assert.strictEqual(slugify('Hello World!'), 'hello-world');
  assert.strictEqual(slugify('  --a   b--  '), 'a-b');
});

